import unittest

from rate_limit import is_allowed


class RateLimitTests(unittest.TestCase):
    def test_allows_when_below_limit(self):
        self.assertTrue(is_allowed([90, 95], now=100, window_seconds=10, limit=3))

    def test_rejects_when_window_is_full(self):
        self.assertFalse(is_allowed([91, 95, 100], now=100, window_seconds=10, limit=3))

    def test_includes_window_boundary(self):
        self.assertFalse(is_allowed([90, 95, 100], now=100, window_seconds=10, limit=3))

    def test_ignores_future_events(self):
        self.assertTrue(is_allowed([95, 101, 102], now=100, window_seconds=10, limit=2))


if __name__ == "__main__":
    unittest.main()
